"""Separate an explicitly requested functional check from paper performance acceptance."""
import re


def comparison_scope(paper_spec, execution_mode='full'):
    if execution_mode == 'smoke':
        return 'functional_check'
    # user_goal is assigned by the API preparation flow, not extracted from a paper
    # or generated by the model. Reruns retain it when their display goal is shortened.
    goal = str((paper_spec or {}).get('user_goal') or '')
    clauses = re.split(r'[。；;\n]', goal)
    for clause in clauses:
        marker = re.search(r'功能(?:测试|检查|验证)|冒烟(?:测试|检查)|functional\s+(?:test|check)|smoke\s+test|pipeline\s+validation', clause, re.I)
        if not marker:
            continue
        prefix = clause[:marker.start()]
        if re.search(r'(?:不(?:要|做|进行|需要)?|无需|取消|without|do\s+not|not\s+a)\s*$', prefix, re.I):
            continue
        return 'functional_check'
    return 'paper_baseline'


FUNCTIONAL_BASIS = '用户明确要求功能检查；论文数值仅供参考，不作性能达标判定，也不据此触发恢复调参'
